        .unwrap()
        .scheduled
        .iter()
        .find(|u| u.target == Target::BaseAlpha)
        .unwrap();
    assert_eq!(parent.dispatch_seconds, Some(0.25));
    assert_eq!(parent.frame_advance, 0.125);
}

fn compare_pose_output(
