    rust_command_script(
        &mut pair.rust,
        "collectgarbage();collectgarbage();assert(message_weak[1]);return ''",
    )
    .unwrap();
    test_support::rust_clear_deferred_actor_messages(&mut pair.rust).unwrap();
    rust_command_script(
        &mut pair.rust,
        "collectgarbage();collectgarbage();assert(message_weak[1]==nil);return ''",
    )
    .unwrap();
}

